{
  "findings": [
    {
      "check_id": "AVD-AWS-0036",
      "title": "Container definition contains a potentially sensitive environment variable 'DATABASE_PASSWORD'",
      "resource": "aws_batch_job_definition.pass3",
      "severity": "CRITICAL",
      "explanation": "The environment variable 'VARNAME' is hardcoded in the container definition. If this variable contains sensitive data, it could be exposed in the AWS Management Console. Sensitive data should be stored securely using secrets."
    }
  ],
  "patched_code": "resource "aws_batch_job_definition" "pass3" {
  name = "tf_test_batch_job_definition"
  type = "container"

  container_properties = jsonencode({
    "command" : ["ls", "-la"],
    "image" : "busybox",
    "memory" : 1024,
    "vcpus" : 1,
    "volumes" : [
      {
        "host" : {
          "sourcePath" : "/tmp"
        },
        "name" : "tmp"
      }
    ],
    "environment" : [],
    "mountPoints" : [
      {
        "sourceVolume" : "tmp",
        "containerPath" : "/tmp",
        "readOnly" : false
      }
    ],
    "ulimits" : [
      {
        "hardLimit" : 1024,
        "name" : "nofile",
        "softLimit" : 1024
      }
    ]
  })
}
",
  "fix_summary": "Removed the hardcoded environment variable 'VARNAME' from the container definition to prevent potential exposure of sensitive data."
}
